    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        else:
            gcd, s, t = extended_gcd(y, x % y)
            s, t = t, s - (x // y) * t
            return (gcd, s, t)

    gcd_val = gcd(a, b)
    if gcd_val != 1:
        return None

    _, x, _ = extended_gcd(a, b)
    return x % b

